p = Path("index.html")
t = p.read_text(encoding="utf-8", errors="replace")

# W3 and W4
for key, block in [("W3", W3_BLOCK), ("W4", W4_BLOCK)]:
    pattern = rf"{key}:\(\)=>[\s\S]*?(?=(?:W\d+:\(\)=>)|(?:const pcvViews=\{{)|(?:F08:))"
    t2, n = re.subn(pattern, block, t, count=1)
    if n != 1:
        pattern2 = rf"{key}:\(\)=>[\s\S]*?(?=(?:W\d+:\(\)=>)|(?:F08:)|(?:const pcvViews=\{{))"
        t2, n = re.subn(pattern2, block, t, count=1)
    if n != 1:
        raise SystemExit(f"{key} replace failed matches={n}")
    t = t2
    print(f"{key} installed")

# F08 — may be named F08: or similar; try several patterns
f08_patterns = [
    r"F08:\(\)=>[\s\S]*?(?=(?:W\d+:\(\)=>)|(?:const pcvViews=\{)|(?:L\d:)|(?:\}\s*;))",
    r"F08:\(\)=>[\s\S]*?(?=(?:const pcvViews=\{))",
    r'"F08"\s*:\s*\(\)\s*=>[\s\S]*?(?=(?:"[A-Z0-9]+"\s*:)|(?:const pcvViews=\{)|(?:\}\s*;))',
]
n_f08 = 0
for pat in f08_patterns:
    t2, n_f08 = re.subn(pat, F08_BLOCK, t, count=1)
    if n_f08 == 1:
        t = t2
        print("F08 installed via pattern")
        break

if n_f08 != 1:
    # Insert before const pcvViews if F08 key exists as stub
    if "F08:" in t:
        t2, n = re.subn(r"F08:\(\)=>[^,]*(?=,|\n)", F08_BLOCK.rstrip(",\n") , t, count=1)
        if n == 1:
            t = t2
            print("F08 installed via stub replace")
            n_f08 = 1
    if n_f08 != 1:
        # Append F08 into widgets object before closing of main widgets map - find W10 and insert after
        if "W10:()=>" in t:
            # insert F08 after W10 block ends - hard; instead inject into a known function if showWidget handles F08
            t = t.replace("const pcvViews={", F08_BLOCK + "\nconst pcvViews={", 1)
            if "SPECIALIST INTELLIGENCE" in t or "F08 — Specialist" in t:
                print("F08 injected before pcvViews")
                n_f08 = 1
            else:
                raise SystemExit("F08 install failed — could not locate insertion point")
        else:
            raise SystemExit("F08 install failed — no W10 and no F08 key")

if "function l3View" not in t:
    raise SystemExit("Safety: l3View missing")
if "What Is the Constraint" not in t and "CONSTRAINT CHARACTERISTICS" not in t:
    raise SystemExit("Safety: W3 content missing")
if "Has the Constraint Shifted" not in t and "CONSTRAINT MIGRATION TIMELINE" not in t:
    raise SystemExit("Safety: W4 content missing")
if "SPECIALIST INTELLIGENCE" not in t and "INTELLIGENCE CHAIN" not in t:
    raise SystemExit("Safety: F08 content missing")

p.write_text(t, encoding="utf-8")
print("W3 + W4 (separate) + F08 installed successfully")
